mapper.select:
SELECT DISTINCT

FROM member_role mr
INNER JOIN sys_role r
    ON r.id = mr.role_id
WHERE mr.tenant_id = #{tenantId}
  AND mr.member_id = #{memberId}
  AND r.tenant_id = #{tenantId}
  AND r.scope_type = #{scopeType}
  AND r.status = 1
ORDER BY r.role_code

SELECT COUNT(1)
FROM tenant_member
WHERE id = #{memberId}
  AND tenant_id = #{tenantId}
  AND status = 1
  AND deleted_at IS NULL
